import { z } from "zod";

export const startConversationSchema = z.object({
  name: z.string().min(1).max(100).optional(),
  email: z.string().email().optional(),
});
export type StartConversationInput = z.infer<typeof startConversationSchema>;

export const widgetMessageSchema = z
  .object({
  body: z.string().max(5000).default(""),
  attachmentIds: z.array(z.string().uuid()).max(5).default([]),
  // Generated by the widget once per message and reused on every retry, so a retry is never stored twice.
  clientMessageId: z
    .string()
    .regex(/^[A-Za-z0-9_-]{8,64}$/)
    .optional(),
  })
  .refine((v) => v.body.trim().length > 0 || v.attachmentIds.length > 0, { message: "Write a message or attach a file", path: ["body"] });
export type WidgetMessageInput = z.infer<typeof widgetMessageSchema>;

export const callRequestSchema = z.object({
  phone: z.string().min(7).max(25),
  preferredTime: z.string().max(100).optional(),
  note: z.string().max(500).optional(),
});
